{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Tobramycin, an aminoglycoside closely related to streptomycin, produced very low or unmeasurable CSF concentrations in neonates after systemic administration, indicating poor CNS access for this chemical class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "A fluorinated aminoglycoside (F-TAC) given intravenously to mice distributed to all tissues except brain and nervous tissue, directly demonstrating negligible brain uptake for aminoglycoside scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Kanamycin appeared in CSF in proportion to blood concentrations in animals, providing some evidence that aminoglycosides can reach CSF; however, the record does not quantify whether the exposure is meaningful.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Streptomycin is a large, highly polar, polycationic aminoglycoside. Direct aminoglycoside evidence (tobramycin, fluorinated aminoglycoside) shows negligible CSF/brain uptake after systemic dosing, and the physicochemical prior predicts no meaningful passive diffusion. Meningeal inflammation in TBM may modestly increase penetration, but the available class evidence does not support adequate CNS exposure; therefore fail.",
  "evidence_gaps": [
    "No direct streptomycin CSF/brain pharmacokinetic measurement is present in the provided evidence set.",
    "Kanamycin CSF detection is unquantified and may reflect low, subtherapeutic levels.",
    "TBM-specific BBB disruption and potential active transport are not directly modeled.",
    "Morgan similarities are low, so class transfer relies on chemical analogy rather than close structural matches."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

